    local function VM_00l0OlOl(d, k, m)
        local R_OO00O = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_OO00O, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_OO00O)
    end

    -- Execution Guard
    local F_0OOO0l = loadstring(VM_00l0OlOl(B_10lOO, 64, 5))
    if F_0OOO0l then
        F_0OOO0l(...)
    end
